import { apiCallPost, apiCallGet } from './index';
import type { Option } from './types';

const prefix = 'trees/';

function apiCallPostTree(path: string, body: unknown) {
    return apiCallPost(prefix + path, body);
}

// TODO: remove next line when the function is used
// eslint-disable-next-line
function apiCallGetTree(path: string) {
    return apiCallGet(prefix + path);
}

/** The general data of the tree, NOT including its structure or autogenerated data */
type TreeData = {
    title: string;
    description: Option<string>;
    bookName: Option<string>;
    bookEdition: Option<string>;
    bookIsbn: Option<string>;
    bookChapter: Option<string>;
    bookExercise: Option<string>;
    assignmentText: Option<string>;
    published: boolean;
};

type TreeId = number;

/** Add a tree to the database */
export function addTree(tree: TreeData): Promise<TreeId> {
    return apiCallPostTree('add-new-tree', tree);
}


class TreeDataForAuthorPage {
    username: string;
    title: string;
    lastEdited: Date;
    published: boolean;
    treeID: number;

    constructor(name: string, title: string, lastEdited: Date, published: boolean, treeID: number) {
        this.username = name;
        this.title = title;
        this.lastEdited = lastEdited;
        this.published = published;
        this.treeID = treeID;
    }
}

/** Receive tree data (username, title, last edited, published, and ID) from database which the user has access to. */
export function apiCallGetTreesFromUser(): TreeDataForAuthorPage[] {
    // Mock items
    const trees: TreeDataForAuthorPage[] = [
        new TreeDataForAuthorPage(
            'Jedidja',
            'Germany in the stone ages had some interesting ideas, but what if this title is realy long, like REALLY REALLY LOOOOOOOOOOOOONG :)',
            new Date(Date.now()), //Random time
            true,
            42
        ),
        new TreeDataForAuthorPage(
            'Theo van den Bogaart',
            'Je kan de boom in!',
            new Date(14658759000), //Again random time
            true,
            67
        )
    ];
    return (trees);
}
